import { Audio } from "@remotion/media";
import { BackgroundMusic } from "./BackgroundMusic";
import { AbsoluteFill, Composition, Sequence, staticFile, useCurrentFrame, useVideoConfig } from "remotion";

type WordTiming = { text: string; startMs: number; endMs: number };
type SceneTiming = { durationMs: number; words: WordTiming[] };
type SpeechSpan = { startMs: number; endMs: number };
type AudioMode = "mix" | "voice-only" | "music-only";

const scenes = [
  { name: "scene-01", text: "Откройте шторы и впустите мягкий утренний свет." },
  { name: "scene-02", text: "Налейте стакан воды и сделайте небольшой глоток." },
  { name: "scene-03", text: "Потянитесь без спешки и спокойно расправьте плечи." },
  { name: "scene-04", text: "Выберите одно простое дело для начала дня." },
];

const SceneCaption = ({ words }: { words: WordTiming[] }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const timeMs = frame / fps * 1000;
  return (
    <div style={{ position: "absolute", bottom: 100, left: 120, right: 120, textAlign: "center", fontFamily: "Arial, sans-serif", fontSize: 42, lineHeight: 1.35, fontWeight: 600, textShadow: "0 2px 12px #000", background: "rgba(0,0,0,0.32)", padding: "20px 28px", borderRadius: 12 }}>
      {words.map((word, index) => <span key={`${word.startMs}-${index}`} style={{ color: timeMs >= word.startMs + 10 / fps * 1000 && timeMs < word.endMs + 10 / fps * 1000 ? "#f3d89b" : "white" }}>{index ? " " : ""}{word.text}</span>)}
    </div>
  );
};

const Film = ({ timings, speech, audioMode }: { timings: SceneTiming[]; speech: SpeechSpan[]; audioMode: AudioMode }) => (
  <AbsoluteFill>
    {audioMode !== "voice-only" && <BackgroundMusic src="music/bg.wav" speech={speech} />}
    {scenes.map((scene, index) => {
      const timing = timings[index];
      const durationInFrames = Math.ceil(10 + timing.durationMs / 1000 * 30 + 15);
      const from = timings.slice(0, index).reduce((total, item) => total + Math.ceil(10 + item.durationMs / 1000 * 30 + 15), 0);
      return (
        <Sequence key={scene.name} from={from} durationInFrames={durationInFrames}>
          <AbsoluteFill style={{ background: "#172c35", color: "white", justifyContent: "center", alignItems: "center", fontSize: 64, padding: 100 }}>{scene.text}</AbsoluteFill>
          <SceneCaption words={timing.words} />
          {audioMode !== "music-only" && <Sequence from={10}><Audio src={staticFile(`voice/${scene.name}.mp3`)} volume={1.26} /></Sequence>}
        </Sequence>
      );
    })}
  </AbsoluteFill>
);

export const RemotionRoot = () => (
  <Composition id="Main" component={Film} width={1920} height={1080} fps={30}
    durationInFrames={600} defaultProps={{ timings: [] as SceneTiming[], speech: [] as SpeechSpan[], audioMode: "mix" as AudioMode }}
    calculateMetadata={async ({ props, abortSignal }) => {
      const timings = await Promise.all(scenes.map(async (scene) => {
        const response = await fetch(staticFile(`voice/${scene.name}.words.json`), { signal: abortSignal });
        return await response.json() as SceneTiming;
      }));
      let from = 0;
      const speech = timings.flatMap((timing) => {
        const offsetMs = (from + 10) / 30 * 1000;
        from += Math.ceil(10 + timing.durationMs / 1000 * 30 + 15);
        return [{ startMs: offsetMs, endMs: offsetMs + timing.durationMs }];
      });
      return { durationInFrames: from, props: { ...props, timings, speech } };
    }}
  />
);

import { Audio } from "@remotion/media";
import { BackgroundMusic } from "./BackgroundMusic";
import { AbsoluteFill, Composition, Sequence, staticFile, useCurrentFrame, useVideoConfig } from "remotion";

type WordTiming = { text: string; startMs: number; endMs: number };
type SceneTiming = { durationMs: number; words: WordTiming[] };
type SpeechSpan = { startMs: number; endMs: number };
type AudioMode = "mix" | "voice-only" | "music-only";
const sceneTexts = [
  "Откройте шторы и впустите мягкий утренний свет.",
  "Налейте стакан воды и сделайте небольшой глоток.",
  "Потянитесь без спешки и спокойно расправьте плечи.",
  "Выберите одно простое дело для начала дня.",
];

const Caption = ({ words }: { words: WordTiming[] }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const timeMs = frame / fps * 1000;
  return (
    <div style={{ position: "absolute", left: 120, right: 120, bottom: 88, textAlign: "center", fontFamily: "Arial, sans-serif", fontSize: 48, lineHeight: 1.35, fontWeight: 600, textShadow: "0 2px 12px #000", background: "rgba(0,0,0,0.32)", padding: "20px 28px", borderRadius: 12 }}>
      {words.map((word, index) => <span key={`${word.startMs}-${index}`} style={{ color: timeMs >= word.startMs + 10 / fps * 1000 && timeMs < word.endMs + 10 / fps * 1000 ? "#f3d89b" : "white" }}>{index ? " " : ""}{word.text}</span>)}
    </div>
  );
};

const Film = ({ timings, speech, audioMode }: { timings: SceneTiming[]; speech: SpeechSpan[]; audioMode: AudioMode }) => (
  <AbsoluteFill>
    {audioMode !== "voice-only" && <BackgroundMusic src="music/bg.wav" speech={speech} />}
    {sceneTexts.map((text, index) => (
      <Sequence key={index} from={index * 150} durationInFrames={150}>
        <AbsoluteFill style={{ background: "#172c35", color: "white", justifyContent: "center", alignItems: "center", fontSize: 64, padding: 100 }}>{text}</AbsoluteFill>
        <Caption words={timings[index]?.words ?? []} />
        {audioMode !== "music-only" && <Sequence from={10}><Audio src={staticFile(`voice/scene-0${index + 1}.mp3`)} volume={1.26} /></Sequence>}
      </Sequence>
    ))}
  </AbsoluteFill>
);

export const RemotionRoot = () => (
  <Composition id="Main" component={Film} width={1920} height={1080} fps={30} durationInFrames={600}
    defaultProps={{ timings: [] as SceneTiming[], speech: [] as SpeechSpan[], audioMode: "mix" as AudioMode }}
    calculateMetadata={async ({ props, abortSignal }) => {
      const timings = await Promise.all([1, 2, 3, 4].map(async (index) => {
        const response = await fetch(staticFile(`voice/scene-0${index}.words.json`), { signal: abortSignal });
        return await response.json() as SceneTiming;
      }));
      const speech = timings.flatMap((timing, index) => [{
        startMs: index * 5000 + 10 / 30 * 1000,
        endMs: index * 5000 + 10 / 30 * 1000 + timing.durationMs,
      }]);
      return { props: { ...props, timings, speech } };
    }}
  />
);

